    65	public final class Pricing {
    66	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
    67	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    68	
    69	    private Pricing() {}
    70	
    71	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    72	
    73	    /** Alta temporada: de 15/12 ao fim de fevereiro e todo o mês de julho. */
    74	    public static boolean isHighSeason(LocalDate night) {
    75	        Month m = night.getMonth();
    76	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    77	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    78	    }
    79	
    80	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    81	        BigDecimal rate = room.nightlyRate();
    82	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON)) : Money.round(rate);
    83	    }
    84	
    85	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    86	        BigDecimal subtotal = Money.ZERO;
    87	        int nights = 0;
    88	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    89	            subtotal = subtotal.add(nightPrice(room, d));
    90	            nights++;
    91	        }
    92	        subtotal = Money.round(subtotal);
    93	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    94	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT)) : Money.ZERO;
    95	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    96	    }
    97	}
