 24	package br.com.marealta;
 25	
 26	import br.com.marealta.domain.AppException;
 27	import br.com.marealta.domain.RatePlan;
 28	import br.com.marealta.domain.Receipt;
 29	import br.com.marealta.domain.Reservation;
 30	import br.com.marealta.event.Message;
 31	import br.com.marealta.service.ReportService;
 32	import br.com.marealta.service.ReservationService;
 33	import br.com.marealta.service.ReservationService.NewReservation;
 34	import br.com.marealta.store.MemoryStore;
 35	import org.junit.jupiter.api.BeforeEach;
 36	import org.junit.jupiter.api.Test;
 37	
 38	import java.math.BigDecimal;
 39	import java.time.LocalDate;
 40	import java.time.YearMonth;
 41	import java.util.List;
 42	
 43	import static org.junit.jupiter.api.Assertions.*;
 44	
 45	class ReservationFlowTest {
 46	    MemoryStore store;
 47	    ReservationService svc;
 48	    ReportService reports;
 49	
 50	    @BeforeEach
 51	    void setUp() {
 52	        store = new MemoryStore();
 53	        svc = new ReservationService(store, Main.subscribers());
 54	        reports = new ReportService(store);
 55	    }
 56	
 57	    NewReservation req(int room, String in, String out, int guests, RatePlan plan) {
 58	        return new NewReservation(room, "Carla Dias", "carla@example.com", "111.222.333-44",
 59	                LocalDate.parse(in), LocalDate.parse(out), guests, plan);
 60	    }
 61	
 62	    static void assertCode(String code, Runnable r) {
 63	        assertEquals(code, assertThrows(AppException.class, r::run).code());
 64	    }
 65	
 66	    @Test
 67	    void highSeasonPricing() {
 68	        Reservation r = svc.create(req(101, "2027-07-10", "2027-07-12", 2, RatePlan.STANDARD));
 69	        assertEquals(new BigDecimal("599.76"), r.total());
 70	        Reservation nr = svc.create(req(102, "2027-03-10", "2027-03-12", 1, RatePlan.NON_REFUNDABLE));
 71	        assertEquals(new BigDecimal("499.80"), nr.subtotal());
 72	        assertEquals(new BigDecimal("74.97"), nr.discount());
 73	        assertEquals(new BigDecimal("424.83"), nr.total());
 74	    }
 75	
 76	    @Test
 77	    void seasonBoundaries() {
 78	        // 14/12 normal, 15/12 alta
 79	        Reservation r = svc.create(req(101, "2027-12-14", "2027-12-16", 1, RatePlan.STANDARD));
 80	        assertEquals(new BigDecimal("549.78"), r.subtotal());
 81	    }
 82	
 83	    @Test
 84	    void confirmationSendsFourMessagesAndReceipt() {
 85	        Reservation r = svc.create(req(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));
 86	        svc.confirm("1");
 87	        List<Message> ms = svc.messages();
 88	        assertEquals(3, ms.size());
 89	        Message guest = ms.stream().filter(m -> m.to().equals("carla@example.com")).findFirst().orElseThrow();
 90	        assertEquals("Reserva confirmada - Pousada Maré Alta", guest.subject());
 91	        assertEquals("Olá, Carla Dias!\n\nSua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
 92	                + "Comprovante de reserva nº 1\nHóspede: Carla Dias (CPF 111.222.333-44)\nQuarto: 201 (DELUXE)\n"
 93	                + "Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias\nDiárias: R$ 779,80\nTotal: R$ 779,80\n\n"
 94	                + "A entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!", guest.body());
 95	        assertTrue(ms.stream().anyMatch(m -> m.to().equals("governanca@pousadamarealta.com.br")
 96	                && m.subject().equals("Reserva confirmada - quarto 201")));
 97	        assertTrue(ms.stream().anyMatch(m -> m.to().equals("financeiro@pousadamarealta.com.br")
 98	                && m.subject().equals("Pagamento recebido - reserva 1") && m.body().contains("R$ 779,80")));
 99	        assertEquals(r.total(), svc.get("1").amountPaid());
100	    }
