102	    @Test
103	    void cancellationRules() {
104	        svc.create(req(101, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD));
105	        svc.cancel("1");
106	        assertTrue(svc.messages().isEmpty());
107	        assertEquals(new BigDecimal("0.00"), svc.get("1").refund());
108	
109	        svc.create(req(101, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD));
110	        svc.confirm("2");
111	        int before = svc.messages().size();
112	        Reservation c = svc.cancel("2");
113	        assertEquals(c.total(), c.refund());
114	        List<Message> after = svc.messages().subList(before, svc.messages().size());
115	        assertEquals(2, after.size());
116	
117	        svc.create(req(101, "2027-03-10", "2027-03-12", 1, RatePlan.NON_REFUNDABLE));
118	        svc.confirm("3");
119	        before = svc.messages().size();
120	        assertEquals(new BigDecimal("0.00"), svc.cancel("3").refund());
121	        after = svc.messages().subList(before, svc.messages().size());
122	        assertEquals(1, after.size());
123	        assertEquals("Reserva cancelada - quarto 101", after.get(0).subject());
124	        assertCode("OPERATION_NOT_ALLOWED", () -> svc.cancel("3"));
125	    }
126	
127	    @Test
128	    void stateMachineAndDocument() {
129	        svc.create(req(301, "2027-03-10", "2027-03-11", 4, RatePlan.STANDARD));
130	        assertCode("OPERATION_NOT_ALLOWED", () -> svc.document("1"));
131	        assertCode("OPERATION_NOT_ALLOWED", () -> svc.checkIn("1"));
132	        svc.confirm("1");
133	        assertCode("OPERATION_NOT_ALLOWED", () -> svc.confirm("1"));
134	        assertCode("OPERATION_NOT_ALLOWED", () -> svc.checkOut("1"));
135	        svc.checkIn("1");
136	        assertCode("OPERATION_NOT_ALLOWED", () -> svc.cancel("1"));
137	        Receipt r = svc.checkOut("1");
138	        assertEquals("Comprovante de reserva", r.title());
139	        assertTrue(r.toText().contains("1 diária\n"));
140	        assertEquals(r, svc.document("1"));
141	        assertCode("RESERVATION_NOT_FOUND", () -> svc.get("99"));
142	        assertCode("RESERVATION_NOT_FOUND", () -> svc.get("abc"));
143	    }
144	
145	    @Test
146	    void validationAndAvailability() {
147	        assertCode("CAPACITY_EXCEEDED", () -> svc.create(req(101, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD)));
148	        assertCode("INVALID_REQUEST", () -> svc.create(req(101, "2027-03-10", "2027-03-10", 1, RatePlan.STANDARD)));
149	        assertCode("INVALID_REQUEST", () -> svc.create(req(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD)));
150	        assertCode("ROOM_NOT_FOUND", () -> svc.create(req(999, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD)));
151	        svc.create(req(101, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD));
152	        assertCode("ROOM_UNAVAILABLE", () -> svc.create(req(101, "2027-03-11", "2027-03-13", 1, RatePlan.STANDARD)));
153	        svc.create(req(101, "2027-03-12", "2027-03-13", 1, RatePlan.STANDARD)); // sai de manhã, entra à tarde
154	        svc.cancel("1");
155	        svc.create(req(101, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD)); // cancelada libera
156	    }
157	
158	    @Test
159	    void reports() {
160	        svc.create(req(102, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD)); // 1
161	        svc.create(req(101, "2027-03-11", "2027-03-13", 1, RatePlan.NON_REFUNDABLE)); // 2
162	        svc.create(req(201, "2027-03-11", "2027-03-13", 1, RatePlan.STANDARD)); // 3 pendente
163	        svc.confirm("1");
164	        svc.confirm("2");
165	        assertEquals("room,type,reservation,check_in,check_out\n101,STANDARD,2,2027-03-11,2027-03-13\n"
166	                + "102,STANDARD,1,2027-03-10,2027-03-12\ntotal,2/5\n", reports.occupancy(LocalDate.parse("2027-03-11")));
167	        assertEquals("room,type,reservation,check_in,check_out\n101,STANDARD,2,2027-03-11,2027-03-13\ntotal,1/5\n",
168	                reports.occupancy(LocalDate.parse("2027-03-12")));
169	        svc.cancel("2"); // não reembolsável: continua na receita
170	        assertEquals("reservation,room,check_in,check_out,status,amount\n"
171	                + "1,102,2027-03-10,2027-03-12,CONFIRMED,499.80\n"
172	                + "2,101,2027-03-11,2027-03-13,CANCELLED,424.83\n"
173	                + "total,924.63\n", reports.revenue(YearMonth.parse("2027-03")));
174	    }
175	}

